insert into public.menu_categories (id, name, note, tint, sort) values ('mezza', 'Mezza', 'Small plates to share — French classics with a Beirut accent', '#efe4cf', 1);
insert into public.menu_items (category_id, name, price, picture, photo_url, ingredients, description, tags, sort) values
  ('mezza', 'Hummus à l''huile de truffe', 7, '🍽️', 'images/menu/hummus-truffe.webp', 'Chickpeas, tahini, lemon, garlic, black truffle oil, olive oil', 'Silky chickpea and tahini hummus, finished with a thread of black truffle oil and good olive oil.', 'v', 1),
  ('mezza', 'Moutabal fumé', 7, '🍽️', 'images/menu/moutabal-fume.webp', 'Charred aubergine, tahini, lemon, garlic, pomegranate, parsley', 'Aubergine charred over the flame until smoky, then beaten with tahini and lemon and scattered with pomegranate seeds.', 'v', 2),
  ('mezza', 'Taboulé', 6, '🍽️', 'images/menu/taboule.webp', 'Parsley, mint, bulgur, tomato, spring onion, lemon, olive oil', 'Our Beirut classic: a mountain of finely chopped parsley and mint with a little bulgur, tomato and spring onion, dressed sharp with lemon.', 'vg', 3),
  ('mezza', 'Fattoush', 7, '🍽️', 'images/menu/fattoush.webp', 'Romaine, radish, cucumber, tomato, sumac, toasted pita, pomegranate molasses', 'Crisp romaine, radish and cucumber with sumac and shards of toasted pita, dressed with pomegranate molasses.', 'vg', 4),
  ('mezza', 'Rillettes de poulet', 9, '🍽️', 'images/menu/rillettes-poulet.webp', 'Slow-cooked chicken, butter, thyme, shallot, cornichons, toasted baguette', 'Chicken slow-cooked in butter and thyme, shredded and potted the Loire way. Served with cornichons and toasted baguette.', 'hcg', 5),
  ('mezza', 'Gougères au gruyère', 8, '🍽️', 'images/menu/gougeres.webp', 'Choux pastry, gruyère, butter, egg, nutmeg', 'Warm choux puffs baked with gruyère and a touch of nutmeg. Light, airy and best eaten straight from the oven.', 'vg', 6),
  ('mezza', 'Pâté de campagne (beef & chicken)', 10, '🍽️', 'images/menu/pate-de-campagne.webp', 'Beef, chicken liver, shallot, black pepper, cornichons, Dijon', 'A coarse country terrine of beef and chicken liver with shallot and black pepper, served with cornichons and Dijon mustard.', 'hmc', 7),
  ('mezza', 'Warda — mini croque bites', 9, '🍽️', 'images/menu/mini-croque-bites.webp', 'Brioche, smoked beef, béchamel, emmental', 'Bite-sized croque-monsieur: brioche layered with smoked beef, béchamel and emmental, toasted until golden.', 'hmg', 8),
  ('mezza', 'Labneh aux herbes de Provence', 6, '🍽️', 'images/menu/labneh-herbes.webp', 'Strained yoghurt, herbes de Provence, olive oil, za''atar crisps', 'Thick strained yoghurt swirled with herbes de Provence and olive oil, with crisp za''atar bread for scooping.', 'vg', 9),
  ('mezza', 'Kebbé croustillant', 9, '🍽️', 'images/menu/kebbe-croustillant.webp', 'Bulgur shell, minced beef, onion, pine nuts, seven spices, yoghurt dip', 'Crisp bulgur shells filled with spiced minced beef, onion and pine nuts, served with a cool yoghurt dip.', 'hmg', 10),
  ('mezza', 'Escargots au beurre persillé', 13, '🍽️', 'images/menu/escargots.webp', 'Burgundy snails, garlic butter, parsley, shallot, baguette', 'Burgundy snails baked in garlic and parsley butter, with baguette to mop up every drop.', 'g', 11),
  ('mezza', 'Batata harra', 6, '🍽️', 'images/menu/batata-harra.webp', 'Crispy potatoes, garlic, coriander, chilli, lemon', 'Crispy potatoes tossed with garlic, fresh coriander, chilli and lemon. Beirut''s favourite side, served hot.', 'vs', 12),
  ('mezza', 'Olives & marinated feta', 6, '🍽️', 'images/menu/olives-feta.webp', 'Green and black olives, feta, orange zest, thyme, chilli flakes', 'Green and black olives with feta marinated in orange zest, thyme and a pinch of chilli.', 'v', 13);
