  ('starters', 'Œufs mimosa', 8, '🍽️', 'images/menu/oeufs-mimosa.webp', 'Eggs, mayonnaise, Dijon mustard, chives, paprika', 'Halved eggs filled with their own yolks whipped with mayonnaise and Dijon, topped with chives and paprika.', 'v', 6),
  ('starters', 'Tartare de saumon', 16, '🍽️', 'images/menu/tartare-saumon.webp', 'Fresh salmon, shallot, capers, dill, lime, avocado', 'Fresh salmon cut by hand with shallot, capers and dill, brightened with lime and served with avocado.', 'f', 7),
  ('starters', 'Carpaccio de bœuf', 15, '🍽️', 'images/menu/carpaccio-boeuf.webp', 'Thin-sliced beef fillet, rocket, parmesan, capers, lemon olive oil', 'Paper-thin slices of beef fillet with rocket, parmesan shavings, capers and lemon olive oil.', 'hm', 8),
  ('starters', 'Quiche au bœuf fumé', 11, '🍽️', 'images/menu/quiche-boeuf-fume.webp', 'Shortcrust, eggs, cream, smoked beef, gruyère', 'Shortcrust filled with a soft egg-and-cream custard, smoked beef and gruyère, served warm.', 'hmg', 9),
