  ('starters', 'Salade lyonnaise au bœuf fumé', 13, '🍽️', 'images/menu/salade-lyonnaise.webp', 'Frisée, poached egg, crispy smoked beef strips, croutons, warm vinaigrette', 'Frisée with a poached egg, crispy smoked beef and croutons, tossed in a warm vinaigrette.', 'hmg', 11),
  ('starters', 'Burrata & tomates anciennes', 15, '🍽️', 'images/menu/burrata-tomates.webp', 'Burrata, heirloom tomatoes, basil, olive oil, fleur de sel', 'Creamy burrata with heirloom tomatoes, basil, olive oil and fleur de sel. Simple, and perfect in season.', 'v', 12);
